10	method gcdI(m:int, n:int) returns (d:int)
11	  requires m > 0
12	  ensures   d == gcd(m,n) 
13	{
14	  var x,y := m,n;
15	        d := 1;
16	  while x != y
17	    decreases             x+y
18	    invariant             x > 0 && y > 0
19	    invariant             gcd(x,y) == gcd(m,n)   
20	   { if x > y { x := x-y; } else { y := y-x; }
21	   }
22	  d := x;
23	}
